import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.junit.MockitoJUnitRunner;
import org.traccar.Protocol;
import org.traccar.model.Position;

import io.netty.buffer.Unpooled;
import io.netty.channel.Channel;
import io.netty.channel.embedded.EmbeddedChannel;

import java.nio.charset.StandardCharsets;
import java.util.TimeZone;

import static org.junit.Assert.assertTrue;

@RunWith(MockitoJUnitRunner.class)
public class Gt06ProtocolDecoderTest {

    private Gt06ProtocolDecoder decoder = new Gt06ProtocolDecoder(new Protocol());

    @Test
    public void decodeGpsTest() {
        Position position = new Position();
        ByteBuf buf = Unpooled.wrappedBuffer("Test String".getBytes(StandardCharsets.UTF_8));
        assertTrue(Gt06ProtocolDecoder.decodeGps(position, buf, true, TimeZone.getDefault()));
    }

    @Test
    public void decodeGpsWithFlagsTest() {
        Position position = new Position();
        ByteBuf buf = Unpooled.wrappedBuffer("Test String".getBytes(StandardCharsets.UTF_8));
        assertTrue(Gt06ProtocolDecoder.decodeGps(position, buf, true, true, true, TimeZone.getDefault()));
    }

    @Test
    public void decodeTest() throws Exception {
        Channel channel = new EmbeddedChannel();
        Object msg = Unpooled.wrappedBuffer("Test Message".getBytes(StandardCharsets.UTF_8));
        decoder.decode(channel, null, msg);
        assertTrue(true);
    }

}
